<?php
function count_query(PDO $pdo, string $sql): int { return (int)$pdo->query($sql)->fetchColumn(); }
$canSeeFinance = in_array(current_user()['role_name'] ?? '', ['super_admin','hospital_admin','accountant'], true);
$stats = [
  ['label'=>'Total doctors','value'=>count_query($pdo,"SELECT COUNT(*) FROM doctors"),'icon'=>'fa-user-doctor','tone'=>'blue','note'=>'Registered specialists'],
  ['label'=>'Total patients','value'=>count_query($pdo,"SELECT COUNT(*) FROM patients"),'icon'=>'fa-hospital-user','tone'=>'teal','note'=>'Patient records'],
  ['label'=>'Hospital staff','value'=>count_query($pdo,"SELECT COUNT(*) FROM staff WHERE status='Active'"),'icon'=>'fa-users','tone'=>'purple','note'=>'Active employees'],
  ['label'=>"Today's appointments",'value'=>count_query($pdo,"SELECT COUNT(*) FROM appointments WHERE appointment_date=CURDATE() AND status<>'Cancelled'"),'icon'=>'fa-calendar-check','tone'=>'orange','note'=>'Scheduled visits'],
  ['label'=>'Current admissions','value'=>count_query($pdo,"SELECT COUNT(*) FROM admissions WHERE status='Admitted'"),'icon'=>'fa-bed-pulse','tone'=>'pink','note'=>'Patients in care'],
  ['label'=>'Available beds','value'=>count_query($pdo,"SELECT COUNT(*) FROM beds WHERE status='Available'"),'icon'=>'fa-bed','tone'=>'sky','note'=>'Ready for admission'],
  ['label'=>'Medicine items','value'=>count_query($pdo,"SELECT COUNT(*) FROM medicines"),'icon'=>'fa-pills','tone'=>'green','note'=>'Stock keeping units'],
  ['label'=>'Pending bills','value'=>count_query($pdo,"SELECT COUNT(*) FROM bills WHERE status<>'Paid'"),'icon'=>'fa-file-invoice-dollar','tone'=>'yellow','note'=>'Require settlement'],
];
if (!$canSeeFinance) $stats = array_values(array_filter($stats, fn($item) => $item['label'] !== 'Pending bills'));
$todayIncome = $canSeeFinance ? (float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(payment_date)=CURDATE()')->fetchColumn() : 0.0;
$pendingAmount = $canSeeFinance ? (float)$pdo->query("SELECT COALESCE(SUM(balance),0) FROM bills WHERE status<>'Paid'")->fetchColumn() : 0.0;
$revenueRows = $canSeeFinance
  ? $pdo->query("SELECT DATE_FORMAT(payment_date,'%b %Y') AS month_label, DATE_FORMAT(payment_date,'%Y-%m') AS sort_key, SUM(amount) AS total FROM payments WHERE payment_date >= DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY sort_key,month_label ORDER BY sort_key")->fetchAll()
  : $pdo->query("SELECT DATE_FORMAT(registration_date,'%b %Y') AS month_label, DATE_FORMAT(registration_date,'%Y-%m') AS sort_key, COUNT(*) AS total FROM patients WHERE registration_date >= DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY sort_key,month_label ORDER BY sort_key")->fetchAll();
$departmentRows = $pdo->query('SELECT d.name,COUNT(p.id) AS total FROM departments d LEFT JOIN patients p ON p.department_id=d.id GROUP BY d.id,d.name ORDER BY total DESC LIMIT 7')->fetchAll();
$patientRows = $pdo->query('SELECT id,patient_code,name,phone,registration_date FROM patients ORDER BY id DESC LIMIT 5')->fetchAll();
$appointmentRows = $pdo->query("SELECT a.id,a.appointment_time,a.token_number,a.status,p.name AS patient_name,d.name AS doctor_name,dp.name AS department_name FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id LEFT JOIN departments dp ON dp.id=a.department_id WHERE a.appointment_date=CURDATE() ORDER BY a.appointment_time LIMIT 7")->fetchAll();
$lowStock = $pdo->query('SELECT medicine_name,quantity,low_stock_threshold FROM medicines WHERE quantity<=low_stock_threshold ORDER BY quantity ASC LIMIT 5')->fetchAll();
$expiring = $pdo->query('SELECT medicine_name,expiry_date FROM medicines WHERE expiry_date IS NOT NULL AND expiry_date<=DATE_ADD(CURDATE(),INTERVAL 60 DAY) ORDER BY expiry_date LIMIT 5')->fetchAll();
$monthlyPatients = count_query($pdo,"SELECT COUNT(*) FROM patients WHERE YEAR(registration_date)=YEAR(CURDATE()) AND MONTH(registration_date)=MONTH(CURDATE())");
$appointmentTotal = count_query($pdo,"SELECT COUNT(*) FROM appointments WHERE appointment_date >= DATE_SUB(CURDATE(),INTERVAL 29 DAY)");
?>
<div class="page-heading"><div><span class="eyebrow text-primary">HOSPITAL OVERVIEW</span><h1>Good <?= (int)date('H') < 12 ? 'morning' : ((int)date('H') < 17 ? 'afternoon' : 'evening') ?>, <?= e(explode(' ',current_user()['name'])[0]) ?> <span class="wave">✦</span></h1><p>Here’s what’s happening across Vikram Reddy Hospital today.</p></div><div class="heading-actions"><a class="btn btn-outline-primary" href="<?= e(url('index.php?page=reports')) ?>"><i class="fa-solid fa-chart-line me-2"></i>View reports</a><?php if (can_access('patients')): ?><a class="btn btn-primary" href="<?= e(url('index.php?page=patients')) ?>"><i class="fa-solid fa-plus me-2"></i>Register patient</a><?php endif; ?></div></div>
<div class="stats-grid">
<?php foreach ($stats as $stat): ?><div class="stat-card"><div class="stat-top"><span class="stat-icon <?= e($stat['tone']) ?>"><i class="fa-solid <?= e($stat['icon']) ?>"></i></span><span class="stat-menu"><i class="fa-solid fa-ellipsis"></i></span></div><div class="stat-value"><?= number_format($stat['value']) ?></div><div class="stat-label"><?= e($stat['label']) ?></div><div class="stat-note"><?= e($stat['note']) ?></div></div><?php endforeach; ?>
</div>
<div class="summary-strip"><?php if($canSeeFinance): ?><div class="summary-item"><span class="summary-icon green"><i class="fa-solid fa-indian-rupee-sign"></i></span><div><small>Today's collection</small><strong><?= money($todayIncome) ?></strong></div></div><div class="summary-divider"></div><div class="summary-item"><span class="summary-icon orange"><i class="fa-solid fa-hourglass-half"></i></span><div><small>Outstanding balance</small><strong><?= money($pendingAmount) ?></strong></div></div><div class="summary-divider"></div><?php endif; ?><div class="summary-item"><span class="summary-icon purple"><i class="fa-solid fa-user-plus"></i></span><div><small>New patients this month</small><strong><?= number_format($monthlyPatients) ?></strong></div></div><div class="summary-divider"></div><div class="summary-item"><span class="summary-icon blue"><i class="fa-solid fa-calendar-week"></i></span><div><small>Appointments · last 30 days</small><strong><?= number_format($appointmentTotal) ?></strong></div></div></div>
<div class="row g-4 mt-1"><div class="col-xl-8"><section class="panel-card h-100"><div class="panel-header"><div><h3><?= $canSeeFinance ? 'Revenue overview' : 'Patient registrations' ?></h3><p><?= $canSeeFinance ? 'Payments received over the recent months' : 'New patient registrations over the recent months' ?></p></div><span class="panel-chip"><i class="fa-solid fa-arrow-trend-up me-1"></i> <?= $canSeeFinance ? 'Collections' : 'Registrations' ?></span></div><div class="chart-wrap"><canvas id="revenueChart"></canvas></div></section></div><div class="col-xl-4"><section class="panel-card h-100"><div class="panel-header"><div><h3>Patients by department</h3><p>Registered patient distribution</p></div></div><div class="chart-wrap chart-wrap-doughnut"><canvas id="departmentChart"></canvas></div></section></div></div>
<div class="row g-4 mt-1"><div class="col-xl-7"><section class="panel-card"><div class="panel-header"><div><h3>Today's appointments</h3><p><?= date('l, d F Y') ?></p></div><a class="text-link" href="<?= e(url('index.php?page=appointments')) ?>">Manage appointments <i class="fa-solid fa-arrow-right ms-1"></i></a></div><div class="table-responsive"><table class="table app-table align-middle"><thead><tr><th>Time / Token</th><th>Patient</th><th>Doctor</th><th>Status</th></tr></thead><tbody>
<?php if (!$appointmentRows): ?><tr><td colspan="4"><div class="empty-state py-4"><i class="fa-regular fa-calendar"></i><span>No appointments scheduled for today.</span></div></td></tr><?php else: foreach($appointmentRows as $row): ?><tr><td><strong><?= e(date('h:i A',strtotime($row['appointment_time']))) ?></strong><small class="d-block text-muted"><?= e($row['token_number'] ?: '—') ?></small></td><td><strong><?= e($row['patient_name']) ?></strong><small class="d-block text-muted"><?= e($row['department_name'] ?: 'General') ?></small></td><td><?= e($row['doctor_name']) ?></td><td><span class="status-pill <?= strtolower(str_replace(' ','-',e($row['status']))) ?>"><?= e($row['status']) ?></span></td></tr><?php endforeach; endif; ?>
</tbody></table></div></section></div><div class="col-xl-5"><section class="panel-card"><div class="panel-header"><div><h3>Recent registrations</h3><p>Latest patients added to the system</p></div><a class="text-link" href="<?= e(url('index.php?page=patients')) ?>">View all <i class="fa-solid fa-arrow-right ms-1"></i></a></div><div class="recent-list">
<?php if (!$patientRows): ?><div class="empty-state py-4"><i class="fa-regular fa-user"></i><span>No patients registered yet.</span></div><?php else: foreach($patientRows as $i=>$p): ?><div class="recent-person"><span class="person-avatar tone-<?= $i%5 ?>"><?= e(strtoupper(substr($p['name'],0,1))) ?></span><div class="recent-person-info"><strong><?= e($p['name']) ?></strong><small><?= e($p['patient_code']) ?> · <?= e($p['phone']) ?></small></div><span class="recent-date"><?= e(date('d M',strtotime($p['registration_date']))) ?></span></div><?php endforeach; endif; ?>
</div></section></div></div>
<div class="row g-4 mt-1"><div class="col-xl-6"><section class="panel-card"><div class="panel-header"><div><h3>Stock attention</h3><p>Medicines at or below their reorder level</p></div><a class="text-link" href="<?= e(url('index.php?page=medicines')) ?>">Open pharmacy <i class="fa-solid fa-arrow-right ms-1"></i></a></div><?php if(!$lowStock): ?><div class="empty-state py-3"><i class="fa-solid fa-circle-check"></i><span>No low-stock medicines.</span></div><?php else: foreach($lowStock as $m): ?><div class="alert-row"><span class="alert-row-icon warning"><i class="fa-solid fa-box-open"></i></span><div><strong><?= e($m['medicine_name']) ?></strong><small>Only <?= (int)$m['quantity'] ?> units left · threshold <?= (int)$m['low_stock_threshold'] ?></small></div><span class="mini-tag warning">Low stock</span></div><?php endforeach; endif; ?></section></div><div class="col-xl-6"><section class="panel-card"><div class="panel-header"><div><h3>Expiry watch</h3><p>Medicines expiring within 60 days</p></div></div><?php if(!$expiring): ?><div class="empty-state py-3"><i class="fa-solid fa-circle-check"></i><span>No upcoming medicine expiries.</span></div><?php else: foreach($expiring as $m): ?><div class="alert-row"><span class="alert-row-icon danger"><i class="fa-solid fa-calendar-xmark"></i></span><div><strong><?= e($m['medicine_name']) ?></strong><small>Expiry date: <?= e(date('d M Y',strtotime($m['expiry_date']))) ?></small></div><span class="mini-tag danger">Check expiry</span></div><?php endforeach; endif; ?></section></div></div>
<script>
const revenueLabels = <?= json_encode(array_column($revenueRows,'month_label')) ?>;
const revenueValues = <?= json_encode(array_map('floatval',array_column($revenueRows,'total'))) ?>;
const deptLabels = <?= json_encode(array_column($departmentRows,'name')) ?>;
const deptValues = <?= json_encode(array_map('intval',array_column($departmentRows,'total'))) ?>;
if (window.Chart) {
  new Chart(document.getElementById('revenueChart'), {type:'line',data:{labels:revenueLabels,datasets:[{label:<?= json_encode($canSeeFinance ? 'Revenue' : 'Patients') ?>,data:revenueValues,borderColor:'#2878d0',backgroundColor:'rgba(40,120,208,.10)',fill:true,tension:.38,pointRadius:4,pointHoverRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:(c)=><?= json_encode($canSeeFinance ? ' ₹' : '') ?>+Number(c.raw).toLocaleString('en-IN')}}},scales:{y:{beginAtZero:true,grid:{color:'#edf1f7'},ticks:{callback:(v)=><?= json_encode($canSeeFinance ? '₹' : '') ?>+Number(v).toLocaleString('en-IN')}},x:{grid:{display:false}}}}});
  new Chart(document.getElementById('departmentChart'), {type:'doughnut',data:{labels:deptLabels,datasets:[{data:deptValues,backgroundColor:['#2878d0','#20b8a8','#8c73db','#ffae56','#ee7b91','#55b7d8','#8ac77b'],borderWidth:0,hoverOffset:6}]},options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:7,padding:14,font:{size:10}}}}}});
}
</script>
